#!/usr/bin/env python3
import sys, os, re, json, base64, pwd, pathlib, tempfile, subprocess, shutil, textwrap, html as htmlmod, urllib.parse

# Import data
try:
    import pandoc_data
except ImportError:
    # Try same dir
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    import pandoc_data

PROG = os.path.basename(sys.argv[0]) if len(sys.argv)>0 else "executable"

def get_user_data_dir():
    xdg = os.environ.get("XDG_DATA_HOME")
    if xdg is not None and xdg != "":
        return os.path.join(xdg, "pandoc")
    home = os.environ.get("HOME")
    if home is not None:
        # even if empty, join
        return os.path.join(home, ".local/share/pandoc") if home != "" else ".local/share/pandoc"
    else:
        try:
            pwdir = pwd.getpwuid(os.getuid()).pw_dir
        except Exception:
            pwdir = os.path.expanduser("~")
        return os.path.join(pwdir, ".local/share/pandoc")

def get_help_text():
    # HELP_TXT starts with b'executable [OPTIONS]...'
    # Replace first word with PROG
    data = pandoc_data.HELP_TXT
    # First line: b'executable [OPTIONS] [FILES]\n'
    # Replace up to first space?
    idx = data.find(b' ')
    if idx != -1:
        return PROG.encode() + data[idx:]
    return data

def get_version_text_full():
    # VERSION_TXT is full? Captured via --version (full). Need to replace user data dir line dynamically.
    # VERSION_TXT lines: pandoc..., Features..., Scripting..., User data directory: ..., Copyright...
    # Replace User data directory line
    lines = pandoc_data.VERSION_TXT.decode('utf-8', errors='replace').splitlines(True)
    # Find line starting with "User data directory:"
    out_lines = []
    for line in lines:
        if line.startswith("User data directory:"):
            out_lines.append(f"User data directory: {get_user_data_dir()}\n")
        else:
            out_lines.append(line)
    return "".join(out_lines).encode()

def get_version_text_short():
    # Short version: without Features/Scripting? Captured? We didn't capture short separately.
    # Short is: pandoc 3.9.0.2\nUser data directory: ...\nCopyright...
    # Construct from full by removing Features/Scripting lines
    full = get_version_text_full().decode()
    lines = full.splitlines(True)
    # Remove lines starting with Features: and Scripting engine:
    out = [l for l in lines if not l.startswith("Features:") and not l.startswith("Scripting engine:")]
    return "".join(out).encode()

PYEOF
cat ./pandoc_clone.py
