# Validation helpers
def error_exit(msg, code):
    sys.stderr.write(msg)
    sys.exit(code)

def validate_wrap(val):
    if val not in ('auto','none','preserve'):
        raise OptError('--wrap must be auto, none, or preserve\n', 6)

def validate_eol(val):
    if val not in ('crlf','lf','native'):
        raise OptError('Argument of --eol must be crlf, lf, or native\n', 6)

def validate_track_changes(val):
    if val not in ('accept','reject','all'):
        raise OptError('Argument of --track-changes must be accept, reject, or all\n', 6)

def validate_reference_location(val):
    if val not in ('block','section','document'):
        raise OptError('Argument of --reference-location must be block, section, or document\n', 6)

def validate_email_obf(val):
    if val not in ('references','javascript','none'):
        raise OptError('Argument of --email-obfuscation must be references, javascript, or none\n', 6)

def validate_top_level(val):
    if val not in ('section','chapter','part','default'):
        raise OptError('Argument of --top-level division must be section,  chapter, part, or default\n', 6)

def validate_ipynb(val):
    if val not in ('all','none','best'):
        raise OptError('Argument of --ipynb-output must be all, none, or best\n', 6)

def validate_fig_caption(val):
    if val not in ('above','below'):
        raise OptError('Argument of --figure-caption-position must be above or below\n', 6)

def validate_table_caption(val):
    if val not in ('above','below'):
        raise OptError('Argument of --table-caption-position must be above or below\n', 6)

def validate_markdown_headings(val):
    if val not in ('setext','atx'):
        raise OptError('Argument of --markdown-headings must be setext or atx\n', 6)

def validate_number(val, name, minv=None, maxv=None, msg=None):
    try:
        # Allow float for dpi? dpi must be number >0, can be float? Test dpi=1.5?
        # For columns, tab-stop, dpi: must be number >0 (int? float?)
        # For toc-depth, slide-level, etc.: must be int in range
        if name in ('dpi',):
            f = float(val)
            if f <= 0:
                raise ValueError()
        elif name in ('columns','tab-stop'):
            # Must be int >0? Test columns=1.5? Probably error? Let's assume int.
            # Actually pandoc allows float? Need to test columns=1.5, dpi=1.5, tab-stop=1.5
            # For now, try int, if fails try float?
            try:
                ival = int(val)
                # Check that val is integer string? e.g., "1.5" -> int fails? int("1.5") raises, so error.
                if str(ival) != str(val).strip() and not (val.strip().lstrip('-').isdigit()):
                    # Allow " 1 "? Probably strip?
                    # Simplify: must be digits
                    raise ValueError()
                if ival <= 0:
                    raise ValueError()
            except:
                raise ValueError()
        else:
            ival = int(val)
            if minv is not None and ival < minv:
                raise ValueError()
            if maxv is not None and ival > maxv:
                raise ValueError()
            return ival
    except ValueError:
        if msg:
            raise OptError(msg, 6)
        else:
            raise OptError(f'Invalid argument for --{name}\n', 6)

