def write_rst_inline(inlines, opts):
    parts=[]
    for il in inlines:
        if isinstance(il, Str):
            parts.append(il.text)
        elif isinstance(il, Space):
            parts.append(' ')
        elif isinstance(il, SoftBreak):
            parts.append(' ' if opts.get('wrap','auto')!='preserve' else '\n')
        elif isinstance(il, LineBreak):
            parts.append('\n')
        elif isinstance(il, Emph):
            inner=write_rst_inline(il.content, opts)
            parts.append(f'*{inner}*')
        elif isinstance(il, Strong):
            inner=write_rst_inline(il.content, opts)
            parts.append(f'**{inner}**')
        elif isinstance(il, Strikeout):
            inner=write_rst_inline(il.content, opts)
            parts.append(inner)
        elif isinstance(il, (Superscript, Subscript)):
            inner=write_rst_inline(il.content, opts)
            parts.append(inner)
        elif isinstance(il, Code):
            parts.append(f'``{il.text}``')
        elif isinstance(il, Link):
            inner=write_rst_inline(il.content, opts)
            # RST links: `inner <url>`__? Actually RST `link <http://...>`__? Good. For "[link](http://...)" to rst? What output? Probably "`link <http://...>`__"? Need to test. For simplicity, output inner + " <"+url+">"? Actually "`link <http://...>`__" (with backticks and __). Implement.
            parts.append(f'`{inner} <{il.url}>`__')
        elif isinstance(il, Image):
            alt_inner=write_rst_inline(il.alt, opts)
            parts.append(f'.. image:: {il.url}\n   :alt: {alt_inner}')
        elif isinstance(il, Math):
            parts.append(f':math:`{il.text}`')
        elif isinstance(il, RawInline):
            pass
        elif isinstance(il, Span):
            inner=write_rst_inline(il.content, opts)
            parts.append(inner)
        elif isinstance(il, Quoted):
            inner=write_rst_inline(il.content, opts)
            parts.append(f'"{inner}"' if il.quote_type=='Double' else f"'{inner}'")
        elif isinstance(il, Cite):
            inner=write_rst_inline(il.content, opts)
            parts.append(inner)
        elif isinstance(il, FootnoteRef):
            parts.append(f'[#{il.id}]_')
    return "".join(parts)

